// Reads the signature header and the unparsed request body. The signature is
// HMAC-SHA256 over "<timestamp>.<raw body>"; the next node computes it with the
// secret from the Crypto credential, "Check signature" compares both.
const MAX_AGE_SECONDS = 300;

const request = $input.first().json;
const header = String(request.headers['x-context-reporter-signature'] ?? '');
const match = /^t=(\d{1,12}),v1=([a-f0-9]{64})$/.exec(header);

let rawBody = '';
try {
  rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  rawBody = '';
}

let reason = '';
if (!match) {
  reason = 'missing or malformed signature';
} else if (Math.abs(Date.now() / 1000 - Number(match[1])) > MAX_AGE_SECONDS) {
  reason = 'signature expired';
} else if (rawBody === '') {
  reason = 'empty body (enable "Raw Body" in the webhook node)';
}

return [{
  json: {
    reason,
    timestamp: match ? match[1] : '',
    signature: match ? match[2] : '',
    // Always a value, the Crypto node requires one
    signedPayload: reason === '' ? `${match[1]}.${rawBody}` : '-',
  },
}];

// Compares the signatures in constant time and decides what to do:
// "rejected", "test" (Send test webhook), "report" (report.created) or "ignored".
// Only the verified body is used; headers other than the signature are not signed.
const item = $input.first().json;

function equalInConstantTime(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) {
    return false;
  }
  let difference = 0;
  for (let i = 0; i < a.length; i++) {
    difference |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return difference === 0;
}

let decision = 'rejected';
let reason = item.reason;
let report = null;

if (reason === '' && !equalInConstantTime(item.expectedSignature, item.signature)) {
  reason = 'invalid signature';
}
if (reason === '') {
  let body = null;
  try {
    body = JSON.parse(item.signedPayload.slice(item.timestamp.length + 1));
  } catch (error) {
    reason = 'invalid JSON';
  }
  if (body !== null) {
    if (body.event === 'test') {
      decision = 'test';
    } else if (body.event === 'report.created' && body.report && typeof body.report.id === 'string') {
      decision = 'report';
      report = body.report;
      // Screenshots are not needed below and would only fill the execution data
      for (const attachment of report.attachments ?? []) {
        delete attachment.contentBase64;
      }
    } else {
      decision = 'ignored';
    }
  }
}

return [{ json: { decision, reason, report } }];

// Builds the issue from the verified report. Everything people typed or named
// (title, description, page titles, record labels) is shown as code, so it
// cannot mention users, add links or images, or change the issue layout.
const report = $input.first().json.report;
const context = report.context ?? {};

function code(value) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (text === '') {
    return '';
  }
  const fence = '`'.repeat(Math.max(1, ...(text.match(/`+/g) ?? ['']).map((run) => run.length + 1)));
  return `${fence} ${text} ${fence}`;
}

function block(value) {
  const text = String(value ?? '').trim();
  const fence = '`'.repeat(Math.max(3, ...(text.match(/`+/g) ?? ['']).map((run) => run.length + 1)));
  return `${fence}text\n${text}\n${fence}`;
}

// Links generated by TYPO3 (report, backend and frontend URLs)
function link(label, url) {
  if (typeof url !== 'string' || !/^https?:\/\//i.test(url)) {
    return '';
  }
  let target = url;
  try {
    target = encodeURI(decodeURI(url));
  } catch (error) {
    return '';
  }
  return `[${label}](${target.replace(/[()]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase())})`;
}

const subject = report.subject ?? {};
const page = context.page ?? {};
const lines = [];
const add = (label, value) => {
  if (value !== '') {
    // A pipe would end the table cell, also inside code
    lines.push(`| ${label} | ${value.replace(/\|/g, '\\|')} |`);
  }
};
const subjectId = subject.table && subject.uid ? `${subject.table}:${subject.uid}` : (subject.identifier ?? '');
add('Report', code(report.id));
add('Object', [code(subject.typeLabel), code(subject.label), code(subjectId)].filter((part) => part !== '').join(' '));
add('Page', page.uid ? `${code(page.title)} ${code('[' + page.uid + ']')}` : '');
add('Site', code(context.site?.identifier));
add('Language', code(context.language?.title ?? context.language?.id));
add('Workspace', code(context.workspace?.title));
add('Module', code([context.backend?.module?.group, context.backend?.module?.title].filter(Boolean).join(' › ')));
add('Reporter', code(report.reporter?.name ?? report.reporter?.username));
add('TYPO3 / PHP', code([report.system?.typo3Version, report.system?.phpVersion].filter(Boolean).join(' / ')));
add('Browser', code(report.browser?.summary));
add('Created', code(report.createdAt));

const links = [
  link('Report in TYPO3', report.links?.report),
  link('Open in TYPO3', subject.backendUrl),
  link('Open page', page.frontendUrl),
].filter((part) => part !== '');

const screenshot = (report.attachments ?? []).some((attachment) => attachment.type === 'screenshot')
  ? '\nA screenshot is attached to the report in TYPO3.\n'
  : '';

const description = [
  '### Description',
  block(report.description || '(no description)'),
  '',
  '### TYPO3 context',
  code(report.summary),
  '',
  '| | |',
  '|---|---|',
  ...lines,
  '',
  links.join(' · '),
  screenshot,
  // Found by "Find existing issue", so a repeated delivery does not create a second issue
  `<!-- context-reporter:${report.id} -->`,
].join('\n');

// Plain text for systems without Markdown, e.g. Jira
const plainText = [
  report.description || '(no description)',
  '',
  report.summary ?? '',
  `Report: ${report.id}`,
  report.links?.report ? `Report in TYPO3: ${report.links.report}` : '',
  page.frontendUrl ? `Page: ${page.frontendUrl}` : '',
].filter((line, index) => index < 2 || line !== '').join('\n');

return [{
  json: {
    reportId: report.id,
    title: String(report.title ?? report.id).replace(/\s+/g, ' ').trim().slice(0, 250),
    description,
    plainText,
  },
}];
